insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
insert into public.posts (id, course_id, parent_id, author_id, body, rating, created_at) values
  (md5('nexa-sample:p-mat-1')::uuid, 'mat-105', null, md5('nexa-sample-user:kofi.mensah')::uuid, 'Do the tutorial sheets every week. Most of the exam questions look like the tutorial ones, so leaving them until revision week makes it much harder. Complex numbers and matrices come up every year.', 4, now() - interval '30 hours'),
  (md5('nexa-sample:p-mat-2')::uuid, 'mat-105', null, md5('nexa-sample-user:selorm.agbeko')::uuid, 'I’m not at UCC. I’m preparing for engineering school next year and following this course list. Which textbook covers the complex numbers section best?', null, now() - interval '52 hours'),
  (md5('nexa-sample:p-mat-3')::uuid, 'mat-105', null, md5('nexa-sample-user:efua.quansah')::uuid, 'The pace is fast after mid-sem. Limits and differentiation take only two weeks. If you struggle with the algebra, find a study group early.', 3, now() - interval '6 hours'),
  (md5('nexa-sample:p-gen103-1')::uuid, 'gen-103', null, md5('nexa-sample-user:yaw.boateng')::uuid, 'Always draw the free-body diagram first, even when the question doesn’t ask for it. Half the marks in the ladder and incline questions come from getting the forces right.', 4, now() - interval '40 hours'),
  (md5('nexa-sample:p-gen105-1')::uuid, 'gen-105', null, md5('nexa-sample-user:abena.sarpong')::uuid, 'Best Level 100 course in my opinion. The labs make Kirchhoff’s laws click. Watch the short Ohm’s law video in Materials before the first lab.', 5, now() - interval '18 hours'),
  (md5('nexa-sample:p-cms-1')::uuid, 'cms-107', null, md5('nexa-sample-user:efua.quansah')::uuid, 'Don’t sleep on CMS. The essay question carries the most marks, and they penalise poor paragraphing. Practise summaries with a word count. Going over the limit costs you.', 4, now() - interval '70 hours'),
  (md5('nexa-sample:p-acc-1')::uuid, 'acc-101', null, md5('nexa-sample-user:ama.owusu')::uuid, 'If the double-entry rule doesn’t make sense yet, read the one-page notes here and do ten journal entries every day for a week. After that, the profit or loss statement questions are straightforward.', 4, now() - interval '22 hours'),
  (md5('nexa-sample:p-nur-1')::uuid, 'nur-101', null, md5('nexa-sample-user:abena.sarpong')::uuid, 'Learn the bones with flashcards and use the skeleton in the lab whenever it’s free. Section A is quick marks if you know your definitions.', 5, now() - interval '90 hours'),
  (md5('nexa-sample:p-eco-1')::uuid, 'eco-101', null, md5('nexa-sample-user:kwesi.arthur')::uuid, 'The demand and supply diagrams are easy marks, but elasticity calculations trip people up. Practise percentage changes.', 3, now() - interval '12 hours'),
  (md5('nexa-sample:p-cms-2')::uuid, 'cms-107', null, md5('nexa-sample-user:gifty.appiah')::uuid, 'Announcement: from this week, the Thursday CMS 107 tutorial moves from the old lecture room to the Science lecture theatre (SLT). Same time, 2–4 pm. Bring your corrected essay drafts. We’ll go through paragraph unity and topic sentences.', null, now() - interval '20 hours'),
  (md5('nexa-sample:p-cms-3')::uuid, 'cms-107', null, md5('nexa-sample-user:akua.darko')::uuid, 'Concord errors cost me marks in the first quiz, so here’s what I learnt. The verb agrees with the real subject, not the noun closest to it.
insert into public.posts (id, course_id, parent_id, author_id, body, rating, created_at) values
  (md5('nexa-sample:p-mat-1-r1')::uuid, 'mat-105', md5('nexa-sample:p-mat-1')::uuid, md5('nexa-sample-user:ama.owusu')::uuid, 'True. The 2023 and 2024 papers both had De Moivre questions. The notes in Materials cover them well.', null, now() - interval '26 hours'),
  (md5('nexa-sample:p-mat-1-r2')::uuid, 'mat-105', md5('nexa-sample:p-mat-1')::uuid, md5('nexa-sample-user:esi.amoah')::uuid, 'Good advice. I’d add: show every step in Cramer’s rule questions. Method marks are where most people lose points.', null, now() - interval '20 hours'),
  (md5('nexa-sample:p-mat-2-r1')::uuid, 'mat-105', md5('nexa-sample:p-mat-2')::uuid, md5('nexa-sample-user:yaw.boateng')::uuid, 'K.A. Stroud’s Engineering Mathematics. The library has copies and the examples are very close to what we do.', null, now() - interval '49 hours'),
  (md5('nexa-sample:p-gen103-1-r1')::uuid, 'gen-103', md5('nexa-sample:p-gen103-1')::uuid, md5('nexa-sample-user:nana.addo')::uuid, 'Exactly. I’ve added a free-body diagram sheet under Materials. Check your sign convention before you resolve forces.', null, now() - interval '35 hours'),
  (md5('nexa-sample:p-cms-1-r1')::uuid, 'cms-107', md5('nexa-sample:p-cms-1')::uuid, md5('nexa-sample-user:kwesi.arthur')::uuid, 'How many words for the summary question? I keep going over.', null, now() - interval '66 hours'),
  (md5('nexa-sample:p-cms-1-r2')::uuid, 'cms-107', md5('nexa-sample:p-cms-1')::uuid, md5('nexa-sample-user:efua.quansah')::uuid, 'Usually 80–100. Underline the main idea in each paragraph first, then write.', null, now() - interval '65 hours'),
  (md5('nexa-sample:p-cms-2-r1')::uuid, 'cms-107', md5('nexa-sample:p-cms-2')::uuid, md5('nexa-sample-user:kojo.ansah')::uuid, 'Thank you, madam. Noted.', null, now() - interval '18 hours'),
  (md5('nexa-sample:p-cms-2-r2')::uuid, 'cms-107', md5('nexa-sample:p-cms-2')::uuid, md5('nexa-sample-user:afia.boakye')::uuid, 'Please, is it for all the tutorial groups or only group B?', null, now() - interval '15 hours'),
  (md5('nexa-sample:p-cms-2-r3')::uuid, 'cms-107', md5('nexa-sample:p-cms-2')::uuid, md5('nexa-sample-user:gifty.appiah')::uuid, 'All groups. The old room is being used for exams that week.', null, now() - interval '12 hours'),
  (md5('nexa-sample:p-cms-3-r1')::uuid, 'cms-107', md5('nexa-sample:p-cms-3')::uuid, md5('nexa-sample-user:kwame.asante')::uuid, 'Very helpful. What about “neither … nor”? Is it “Neither the lecturer nor the students was there” or “were there”?', null, now() - interval '130 hours'),
  (md5('nexa-sample:p-cms-3-r2')::uuid, 'cms-107', md5('nexa-sample:p-cms-3')::uuid, md5('nexa-sample-user:akua.darko')::uuid, 'Use the subject closest to the verb (the proximity rule). “Neither the lecturer nor the students were there.” But “Neither the students nor the lecturer was there.”', null, now() - interval '126 hours'),
  (md5('nexa-sample:p-cms-3-r3')::uuid, 'cms-107', md5('nexa-sample:p-cms-3')::uuid, md5('nexa-sample-user:gifty.appiah')::uuid, 'Correct. One more that comes up often: “A number of students are absent” (plural) but “The number of students is small” (singular).', null, now() - interval '110 hours'),
  (md5('nexa-sample:p-cms-4-r1')::uuid, 'cms-107', md5('nexa-sample:p-cms-4')::uuid, md5('nexa-sample-user:adwoa.frimpong')::uuid, 'Same here. I come 30 minutes early just to get a seat in the front rows.', null, now() - interval '290 hours'),
  (md5('nexa-sample:p-cms-4-r2')::uuid, 'cms-107', md5('nexa-sample:p-cms-4')::uuid, md5('nexa-sample-user:kojo.ansah')::uuid, 'I understand, but I don’t think the lecture is the main problem. The tutorials are small groups and that’s where the real learning happens. The lecture is mostly an overview.', null, now() - interval '280 hours'),
  (md5('nexa-sample:p-cms-4-r3')::uuid, 'cms-107', md5('nexa-sample:p-cms-4')::uuid, md5('nexa-sample-user:adwoa.frimpong')::uuid, 'Fair point, Kojo, but not everyone can make every tutorial. Some of us have clashes with practicals, so the lecture is our only contact.', null, now() - interval '270 hours'),
  (md5('nexa-sample:p-cms-4-r4')::uuid, 'cms-107', md5('nexa-sample:p-cms-4')::uuid, md5('nexa-sample-user:naa.lamptey')::uuid, 'Suggestion: let’s ask the course rep to request that the slides be posted before each lecture. Then even from the back you can follow along.', null, now() - interval '250 hours'),
  (md5('nexa-sample:p-cms-5-r1')::uuid, 'cms-107', md5('nexa-sample:p-cms-5')::uuid, md5('nexa-sample-user:gifty.appiah')::uuid, 'You’re welcome to follow along. Start with paragraph structure: one main idea per paragraph, stated in a clear topic sentence. Read a good newspaper editorial every day and notice how each paragraph is built.', null, now() - interval '480 hours'),
  (md5('nexa-sample:p-cms108-1-r1')::uuid, 'cms-108', md5('nexa-sample:p-cms108-1')::uuid, md5('nexa-sample-user:afia.boakye')::uuid, 'Madam, when do we use “Yours faithfully” and when “Yours sincerely”?', null, now() - interval '390 hours'),
  (md5('nexa-sample:p-cms108-1-r2')::uuid, 'cms-108', md5('nexa-sample:p-cms108-1')::uuid, md5('nexa-sample-user:gifty.appiah')::uuid, 'If you open with “Dear Sir/Madam” (you don’t know the name), close with “Yours faithfully”. If you open with the person’s name, “Dear Mrs Owusu”, close with “Yours sincerely”. Note that there is no apostrophe and no capital letter on the second word.', null, now() - interval '385 hours'),
  (md5('nexa-sample:p-cms108-2-r1')::uuid, 'cms-108', md5('nexa-sample:p-cms108-2')::uuid, md5('nexa-sample-user:issah.mohammed')::uuid, 'The “own words” part is hard. If I change the words too much, I worry that I’m changing the meaning.', null, now() - interval '200 hours'),
  (md5('nexa-sample:p-cms108-2-r2')::uuid, 'cms-108', md5('nexa-sample:p-cms108-2')::uuid, md5('nexa-sample-user:adwoa.frimpong')::uuid, 'Change the sentence structure and keep the key terms. “Deforestation reduces rainfall” can become “When forests are cut down, the area receives less rain.”', null, now() - interval '196 hours'),
  (md5('nexa-sample:p-cms108-3-r1')::uuid, 'cms-108', md5('nexa-sample:p-cms108-3')::uuid, md5('nexa-sample-user:naa.lamptey')::uuid, 'Count me in. Can we also do comprehension once in a while?', null, now() - interval '55 hours'),
  (md5('nexa-sample:p-cms108-3-r2')::uuid, 'cms-108', md5('nexa-sample:p-cms108-3')::uuid, md5('nexa-sample-user:efua.quansah')::uuid, 'I’ll come next Saturday. Marking someone else’s essay is the fastest way to see your own mistakes.', null, now() - interval '50 hours'),
  (md5('nexa-sample:p-cms108-4-r1')::uuid, 'cms-108', md5('nexa-sample:p-cms108-4')::uuid, md5('nexa-sample-user:kojo.ansah')::uuid, 'Yes, near the end of the semester. We were taught: title, introduction (terms of reference), findings, conclusions, recommendations.', null, now() - interval '690 hours'),
  (md5('nexa-sample:p-cms108-4-r2')::uuid, 'cms-108', md5('nexa-sample:p-cms108-4')::uuid, md5('nexa-sample-user:gifty.appiah')::uuid, 'That’s right. For a memo, use To / From / Date / Subject at the top, with no salutation or complimentary close. Keep it to one page if you can.', null, now() - interval '650 hours'),
  (md5('nexa-sample:p-cms108-5-r1')::uuid, 'cms-108', md5('nexa-sample:p-cms108-5')::uuid, md5('nexa-sample-user:kwame.asante')::uuid, 'Agreed. The last two were due in the same week as the ILT quiz.', null, now() - interval '145 hours'),
  (md5('nexa-sample:p-cms108-5-r2')::uuid, 'cms-108', md5('nexa-sample:p-cms108-5')::uuid, md5('nexa-sample-user:akua.darko')::uuid, 'I see it differently. Each one is short, and writing is a skill you only improve by practising. I’d rather have small assignments than one big one that carries all the marks.', null, now() - interval '140 hours'),
  (md5('nexa-sample:p-cms108-5-r3')::uuid, 'cms-108', md5('nexa-sample:p-cms108-5')::uuid, md5('nexa-sample-user:gifty.appiah')::uuid, 'Thank you for raising it politely. The short assignments are deliberate, because writing improves with regular feedback. I’ll avoid due dates in the ILT quiz week and post the full schedule for the rest of the semester.', null, now() - interval '120 hours'),
  (md5('nexa-sample:p-cms108-5-r4')::uuid, 'cms-108', md5('nexa-sample:p-cms108-5')::uuid, md5('nexa-sample-user:naa.lamptey')::uuid, 'Thank you, madam. A schedule will help a lot.', null, now() - interval '110 hours'),
